<?php
require_once __DIR__.'/../includes/component_service.php';
require_once __DIR__.'/../includes/ata_chapters.php'; require_login();
$id=filter_var($_GET['id'] ?? null,FILTER_VALIDATE_INT,['options'=>['min_range'=>1]]); if (!$id) { http_response_code(400); exit('Invalid component ID.'); }
$c=component_query($pdo,$id); if (!$c) { http_response_code(404); exit('Component not found.'); }
$usage=component_usage($c);
$q=$pdo->prepare('SELECT * FROM component_service_requirements WHERE component_id=? ORDER BY id'); $q->execute([$id]); $requirements=$q->fetchAll();
$q=$pdo->prepare('SELECT m.*,a.registration,u.name AS performed_by_name FROM component_movements m LEFT JOIN aircraft a ON a.id=m.aircraft_id LEFT JOIN users u ON u.id=m.performed_by WHERE m.component_id=? ORDER BY m.id DESC LIMIT 50'); $q->execute([$id]); $movements=$q->fetchAll();
$page_title=$c['component_type']; include __DIR__.'/../includes/header.php'; ?>
<h1><?= esc($c['component_type']) ?> — <?= esc($c['serial_number'] ?: $c['part_number']) ?></h1>
<div class="grid"><div class="card"><h3>Location</h3><div class="number small-number"><?= $c['location_type']==='AIRCRAFT'?esc($c['registration'] ?? 'Check aircraft'):'Inventory' ?></div><p><?= esc($c['location_type']==='AIRCRAFT'?$c['install_position']:$c['parts_location']) ?></p></div><?php if ($c['track_time']): ?><div class="card"><h3>Time Since New</h3><div class="number"><?= $usage['error']?'Check readings':esc(number_format($usage['tsn'],1)) ?></div></div><div class="card"><h3>Time Since Overhaul</h3><div class="number"><?= $usage['error']?'Check readings':($usage['tso']===null?'Set baseline':esc(number_format($usage['tso'],1))) ?></div></div><div class="card"><h3>Time Since Repair</h3><div class="number"><?= $usage['error']?'Check readings':($usage['tsr']===null?'Set baseline':esc(number_format($usage['tsr'],1))) ?></div></div><?php endif; ?><?php if ($c['track_calendar']): ?><div class="card"><h3>Months in service</h3><div class="number"><?= $usage['error']?'—':esc(number_format($usage['months'],1)) ?></div><small><?= $usage['error']?'':(int)$usage['days'].' accumulated days; approximate months' ?></small></div><?php endif; ?><?php if ($c['track_cycles']): ?><div class="card"><h3>Component cycles</h3><div class="number"><?= $usage['error']?'—':(int)$usage['cycles'] ?></div></div><?php endif; ?></div>
<p><strong>ATA Chapter:</strong> <?= esc(ata_label($c['ata_chapter'])) ?></p><p><strong>Tracking:</strong> <?= $c['track_calendar']?'Calendar ':'' ?><?= $c['track_time']?'Time ':'' ?><?= $c['track_cycles']?'Cycles':'' ?></p><p><strong>Part:</strong> <?= esc($c['part_number']) ?> · <strong>Serial:</strong> <?= esc($c['serial_number']) ?> · <strong>Manufacturer:</strong> <?= esc($c['manufacturer']) ?></p>
<?php if ($c['location_type']==='AIRCRAFT'): ?><p><strong>Aircraft total time at install:</strong> <?= esc($c['installed_aircraft_total_time']) ?> · <strong>Aircraft cycles at install:</strong> <?= esc($c['installed_aircraft_cycles']) ?> · <strong>TSN at install:</strong> <?= $c['track_time']?esc($c['service_hours_base']):'—' ?> · <strong>TSO at install:</strong> <?= esc($c['tso_hours_base'] ?? '—') ?> · <strong>TSR at install:</strong> <?= esc($c['tsr_hours_base'] ?? '—') ?> · <strong>Component cycles at install:</strong> <?= $c['track_cycles']?esc($c['service_cycles_base']):'—' ?></p><p><strong>Installed:</strong> <?= esc($c['installed_date'] ?? '—') ?> · <strong>Position:</strong> <?= esc($c['install_position'] ?? '—') ?></p><?php else: ?><p><strong>Parts location:</strong> <?= esc($c['parts_location']) ?></p><?php endif; ?>
<?php if ($usage['error']): ?><div class="error">Aircraft readings moved below the installation baseline. Review aircraft total time and cycles before relying on service flags.</div><?php endif; ?>
<?php if (in_array(user()['role'],['ADMIN','MANAGER','MECHANIC'])): ?><div class="actions"><a class="btn" href="service.php?component_id=<?= (int)$id ?>">+ Add service data</a><a class="btn secondary" href="edit.php?id=<?= (int)$id ?>">Edit component</a><a class="btn secondary" href="move.php?id=<?= (int)$id ?>"><?= $c['location_type']==='AIRCRAFT'?'Move to inventory':'Install on aircraft' ?></a><a class="btn secondary" href="baseline.php?id=<?= (int)$id ?>">Set installation baseline</a></div><?php endif; ?>
<h2>Service requirements</h2><div class="table-wrap"><table><tr><th>Requirement</th><th>Description</th><th>Last complied</th><th>Interval</th><th>Next due</th><th>Hours remaining</th><th>Cycles remaining</th><th>Calendar remaining</th><th>Warning</th><th>Status</th><th>Action</th></tr>
<?php foreach ($requirements as $r): $r=array_merge(['track_calendar'=>$c['track_calendar'],'track_time'=>$c['track_time'],'track_cycles'=>$c['track_cycles']],$r); $status=component_service_status($r,$usage); $remaining=component_service_remaining($r,$usage); ?><tr><td><?= esc($r['requirement_type']) ?></td><td><?= esc($r['description']) ?></td><td><?= esc($r['last_date'] ?? '—') ?><br>Hours <?= esc($r['last_hours'] ?? '—') ?> · Cycles <?= esc($r['last_cycles'] ?? '—') ?></td><td><?= $r['calendar_interval_value']!==null?esc($r['calendar_interval_value'].' '.strtolower($r['calendar_interval_unit'])):'—' ?><br><?= esc($r['interval_hours'] ?? '—') ?> <?= esc($r['time_basis']) ?> hours (<?= $r['time_limit_mode']==='ABSOLUTE'?'absolute':'after compliance' ?>) · <?= esc($r['interval_cycles'] ?? '—') ?> cycles (<?= $r['cycle_limit_mode']==='ABSOLUTE'?'absolute':'after compliance' ?>)</td><td><?= esc($r['due_date'] ?? '—') ?><br>Hours <?= esc($r['due_hours'] ?? '—') ?> · Cycles <?= esc($r['due_cycles'] ?? '—') ?></td><td><?= esc(remaining_label($remaining['hours'],'hr',1)) ?></td><td><?= esc(remaining_label($remaining['cycles'],'cycles')) ?></td><td><?= esc(remaining_label($remaining['days'],'days')) ?></td><td><?= (int)$r['warning_calendar_months'] ?> mo · <?= esc($r['warning_hours']) ?> hr · <?= (int)$r['warning_cycles'] ?> cy</td><td class="<?= in_array($status,['Past due','Check readings','Set time baseline'],true)?'red':($status==='Tracked'?'green':'yellow') ?>"><?= esc($status) ?></td><td><?php if (in_array(user()['role'],['ADMIN','MANAGER','MECHANIC'])): ?><a href="service.php?id=<?= (int)$r['id'] ?>">Edit</a><?php endif; ?></td></tr><?php endforeach; ?><?php if (!$requirements): ?><tr><td colspan="11">No service requirements yet.</td></tr><?php endif; ?></table></div>
<h2>Movement history</h2><div class="table-wrap"><table><tr><th>Date</th><th>Action</th><th>Aircraft / parts location</th><th>Position</th><th>Component hours</th><th>Cycles</th><th>Months in service</th><th>Recorded by</th><th>Note</th></tr><?php foreach ($movements as $m): ?><tr><td><?= esc($m['movement_date']) ?></td><td><?= esc($m['action']) ?></td><td><?= esc($m['registration'] ?? $m['parts_location']) ?></td><td><?= esc($m['install_position']) ?></td><td><?= esc($m['component_hours']) ?></td><td><?= (int)$m['component_cycles'] ?></td><td><?= esc(number_format((int)$m['service_days']/30.4375,1)) ?></td><td><?= esc($m['performed_by_name'] ?? 'Former user') ?></td><td><?= esc($m['note']) ?></td></tr><?php endforeach; ?><?php if (!$movements): ?><tr><td colspan="9">No movements recorded since V10.</td></tr><?php endif; ?></table></div>
<?php include __DIR__.'/../includes/footer.php'; ?>
